public sealed interface Result permits Success, Failure {
    record Success(String data, int code) implements Result {}
    record Failure(Throwable cause, int errorCode) implements Result {}
}

public class SwitchPatternDemo {
    public String handleResult(Result result) {
        return switch (result) {
            case null -> "Received null result";
            case Result.Success(String data, int code) when code == 200 -> 
                "Success with payload: " + data;
            case Result.Success s -> 
                "Success with non-standard code: " + s.code();
            case Result.Failure(var cause, var code) -> 
                "Failed [" + code + "]: " + cause.getMessage();
        };
    }
}
